mapper.select:
SELECT r.mail_re_no ,r.mail_receiver ,r.read_check ,FIND_CODENAME(r.read_check) AS read_check_name ,r.mail_no ,m.mail_title AS receive_title ,m.mail_contents AS receive_contents ,m.mail_send_date AS receive_date ,m.mail_type ,FIND_CODENAME(m.mail_type) AS mail_type_name ,m.class_id ,m.sender_id ,b.member_name AS sender_name ,FIND_CODENAME(b.authority) AS sender_authority ,m.notice_no ,n.notice_type AS notice_set
FROM mail_receivers r join mail m ON(r.mail_no = m.mail_no) join member b ON(m.sender_id = b.member_id) left outer join notice n ON(m.notice_no = n.notice_no)
WHERE r.mail_re_no = #{mailReNo}

mapper.insert:

	SELECT NVL(MAX(mail_re_no), 0) + 1
	FROM mail_receivers

INSERT 
INTO mail_receivers(
					mail_re_no
					,mail_no
					,read_check
					,mail_receiver
				)	
			VALUES(
					#{mailReNo}
					,#{mailNo}
					,'F201'
					,#{mailReceiver}
				)

mapper.update:
UPDATE mail_receivers
SET	read_check = 'F202'
WHERE mail_re_no = #{mailReNo}
